content.content:
    OwnerFields:
      title: Owner fields
      description: Editable fields of a pet owner.
      type: object
      properties:
        firstName:
          title: First name
          description: The first name of the pet owner.
          type: string
          minLength: 1
          maxLength: 30
          pattern: "^[\\p{L}]+([ '-][\\p{L}]+){0,2}$"
          example: George
        lastName:
          title: Last name
          description: The last name of the pet owner.
          type: string
          minLength: 1
          maxLength: 30
          pattern: "^[\\p{L}]+([ '-][\\p{L}]+){0,2}\\.?$"
          example: Franklin
        address:
          title: Address
          description: The postal address of the pet owner.
          type: string
          minLength: 1
          maxLength: 255
          example: '110 W. Liberty St.'
        city:
          title: City
          description: The city of the pet owner.
          type: string
          minLength: 1
          maxLength: 80
          example: Madison
        telephone:
          title: Telephone number
          description: >-
            The telephone number of the pet owner, stored and returned in E.164 form. Spaces,
            dashes and brackets are removed. A leading '+' and country code are kept; otherwise
            a single leading '0' is dropped and country code '+61' is assumed. Between 8 and 15
            digits must follow the '+', e.g. '0412 345 678' is stored as '+61412345678'.
          type: string
          minLength: 1
          maxLength: 20
          example: '+61412345678'
        email:
          title: Email address
          description: >-
            The optional email address of the pet owner. When present it must be a syntactically
            valid address; it is stored and returned lower-cased.
          type: string
          format: email
          maxLength: 255
          example: 'george.franklin@example.com'
        registrationDate:
          title: Registration date
          description: >-
            The date the owner registered with the clinic. On create, when omitted it defaults to
            the server's current date. A Saturday or Sunday (supplied or defaulted) is rolled
            forward to the following Monday.
          type: string
          format: date
          example: '2020-06-15'
        sharesHousehold:
          title: Shares household
          description: >-
            Set to true on create to allow the owner even though another owner already has the
            same last name and address (compared case-insensitively with collapsed whitespace).
            Otherwise such a create is rejected with 409 Conflict. When true and such owners exist,
            the new owner joins their household and all of them share the same 'householdId'.
            Not stored.
          type: boolean
          writeOnly: true
          example: false
      required:
        - firstName
        - lastName
        - address
        - city
        - telephone
    Owner:
      title: Owner
      description: A pet owner.
      allOf:
        - $ref: '#/components/schemas/OwnerFields'
        - type: object
          properties:
            id:
              title: ID
              description: The ID of the pet owner.
              type: integer
              format: int32
              minimum: 0
              example: 1
              readOnly: true
            pets:
              title: Pets
              description: The pets owned by this individual including any booked vet visits.
              type: array
              items:
                $ref: '#/components/schemas/Pet'
              readOnly: true
            displayName:
              title: Display name
              description: The owner's name formatted as 'LastName, FirstName' from the stored names.
              type: string
              example: 'Franklin, George'
              readOnly: true
            initials:
              title: Initials
              description: The upper-cased first letters of the owner's first and last names, dot-separated with a trailing dot.
              type: string
              example: 'G.F.'
              readOnly: true
            customerCode:
              title: Customer code
              description: >-
                Assigned on create as '<CITY3>-<LAST3>-<NNNN>': the upper-cased first three letters
                of the city, a dash, the upper-cased first three letters of the last name, a dash, and
                a per-city 4-digit zero-padded sequence equal to one more than the number of owners
                already in that city (compared case-insensitively) at creation time.
              type: string
              example: 'MAD-FRA-0002'
              readOnly: true
            householdId:
              title: Household ID
              description: >-
                Stable identifier shared by owners in the same household. Assigned when an owner is
                created with 'sharesHousehold' set to true at the address of an existing owner with the
                same last name; the existing household's ID is reused, or a new one is generated and
                also given to the existing owners. Absent for owners not in a shared household.
              type: string
              example: '3f2b8c1e-7a4d-4e8b-9c1a-2d5e6f7a8b9c'
              readOnly: true
            namesakeCount:
              title: Namesake count
              description: >-
                Assigned on create: the number of owners that already existed before this owner was
                created with the same first name and last name, compared case-insensitively.
              type: integer
              format: int32
              minimum: 0
              example: 0
              readOnly: true
            membershipNumber:
              title: Membership number
              description: >-
                Formatted as '<customerCode>-M<YY>' where YY is the last two digits of the
                registration date's year, e.g. 'SYD-SMI-0007-M26'. Absent when the owner has no
                customer code or registration date.
              type: string
              example: 'MAD-FRA-0002-M20'
              readOnly: true
            membershipTier:
              title: Membership tier
              description: >-
                'SILVER' when 'namesakeCount' is 0 and an email is present, otherwise 'BRONZE'.
              type: string
              example: 'SILVER'
              readOnly: true
            locality:
              title: Locality
              description: >-
                The region derived from the city using the fixed table Sydney -> 'NSW',
                Melbourne -> 'VIC', Brisbane -> 'QLD'; 'UNKNOWN' for any other city.
              type: string
              example: 'NSW'
              readOnly: true
          required:
            - pets
    OwnerPage:
      title: Owner page
      description: A page of pet owners.
      type: object
      properties:
package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;

import java.util.Collection;
import java.util.List;
import java.util.Map;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public interface OwnerMapper {

    Map<String, String> CITY_REGIONS = Map.of(
        "Sydney", "NSW",
        "Melbourne", "VIC",
        "Brisbane", "QLD");

    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
    @Mapping(target = "initials", expression = "java(toInitials(owner))")
    @Mapping(target = "membershipNumber", expression = "java(toMembershipNumber(owner))")
    @Mapping(target = "membershipTier", expression = "java(toMembershipTier(owner))")
    @Mapping(target = "locality", expression = "java(toLocality(owner))")
    @Mapping(target = "sharesHousehold", ignore = true)
    OwnerDto toOwnerDto(Owner owner);

    /**
     * The region of the owner's city from {@link #CITY_REGIONS}, or 'UNKNOWN' when the city is not listed.
     */
    default String toLocality(Owner owner) {
        return owner.getCity() == null ? "UNKNOWN" : CITY_REGIONS.getOrDefault(owner.getCity(), "UNKNOWN");
    }

    /**
     * 'SILVER' when the owner has no namesakes and an email is present, otherwise 'BRONZE'.
     */
    default String toMembershipTier(Owner owner) {
        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
        return hasEmail && noNamesakes ? "SILVER" : "BRONZE";
    }

    /**
     * Builds the membership number '&lt;customerCode&gt;-M&lt;YY&gt;', where YY is the last two digits of
     * the registration date's year.
     */
    default String toMembershipNumber(Owner owner) {
        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
            return null;
        }
        return String.format("%s-M%02d", owner.getCustomerCode(),
            Math.floorMod(owner.getRegistrationDate().getYear(), 100));
    }

    default String toInitials(Owner owner) {
        return initial(owner.getFirstName()) + initial(owner.getLastName());
    }

    private static String initial(String name) {
        return name == null || name.isEmpty() ? "" : Character.toUpperCase(name.charAt(0)) + ".";
    }

    Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    @Mapping(target = "customerCode", ignore = true)
    @Mapping(target = "householdId", ignore = true)
    @Mapping(target = "namesakeCount", ignore = true)
    Owner toOwner(OwnerFieldsDto ownerDto);

    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
        OwnerPageDto ownerPageDto = new OwnerPageDto();
        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
        ownerPageDto.setPage(ownerPage.getNumber());
        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}
